"use strict";const SITE_CONFIG=(function(){try{var e=new XMLHttpRequest;e.open("GET","data/config.json",false);e.send(null);if(e.status===200||(e.status===0&&e.responseText)){return JSON.parse(e.responseText);}throw new Error("HTTP "+e.status);}catch(t){console.error("config: could not load data/config.json - "+t.message);return {};}})();
if(typeof module!=="undefined"&&module.exports){module.exports=SITE_CONFIG;}
